1	product_selection	Selección de Producto	<p>Selecciona el vehículo o maquinaria que deseas financiar. \n            El precio se cargará automáticamente y podrás ver las opciones de financiamiento disponibles.</p>\n            <p><strong>Tip:</strong> Usa el filtro por categoría para encontrar más rápido lo que buscas.</p>	t	2025-05-27 03:51:35.290357+00
2	down_payment	Monto Inicial	<p>El monto inicial es la cantidad que debes pagar al momento de la compra. \n            A mayor inicial, menores serán tus cuotas mensuales.</p>\n            <p><strong>Importante:</strong> No cobramos intereses, solo pagas el valor del vehículo.</p>	t	2025-05-27 03:51:35.294157+00
3	financing_term	Plazo de Financiamiento	<p>Elige el tiempo en meses para pagar el saldo restante. \n            Plazos más largos significan cuotas más bajas, pero más tiempo pagando.</p>	t	2025-05-27 03:51:35.297654+00
4	payment_frequency	Frecuencia de Pago	<p>Selecciona cada cuánto realizarás los pagos:</p>\n            <ul>\n                <li><strong>Semanal:</strong> Un pago cada semana</li>\n                <li><strong>Quincenal:</strong> Un pago cada 15 días</li>\n                <li><strong>Mensual:</strong> Un pago cada mes</li>\n            </ul>	t	2025-05-27 03:51:35.301559+00
5	general	Información General	<p><strong>Proceso de Financiamiento:</strong></p>\n            <ol>\n                <li>Calcula tu financiamiento ideal</li>\n                <li>Envía tu solicitud (requiere registro)</li>\n                <li>Recibe aprobación en 24-48 horas</li>\n                <li>Entrega inmediata del vehículo</li>\n            </ol>\n            <p><strong>Sin letra pequeña:</strong> No cobramos intereses ni comisiones ocultas.</p>	t	2025-05-27 03:51:35.305107+00
\.


